'use strict';
const KEY='vanta-design-review-20261016-v1'; // Preserve the user's existing review state.
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',library:'<rect x="4" y="4" width="5" height="16" rx="1"/><path d="M12 4v16m3-16 5 15"/>',link:'<path d="m10 13 4-4m-7 6-2 2a4 4 0 0 0 6 4l3-3m3-9 2-2a4 4 0 0 0-6-4l-3 3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 3v4l3 1 2 3h4l2-3 3-1v-4l2-3-2-3-3-1-1-3Z"/>',panel:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M14 4v16m3-11h1m-1 4h1"/>',terminal:'<path d="m5 7 5 5-5 5m8 0h6"/>',diff:'<path d="M8 3v12a3 3 0 0 0 3 3h5M16 5v4m-2-2h4"/><circle cx="8" cy="3" r="2"/><circle cx="8" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',folder:'<path d="M3 6h7l2 2h9v12H3Z"/>',file:'<path d="M5 3h9l5 5v13H5Z"/><path d="M14 3v6h5M8 13h8m-8 4h6"/>',plus:'<path d="M12 4v16M4 12h16"/>',mic:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 10v2a6 6 0 0 0 12 0v-2m-6 8v3m-3 0h6"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`}
const initial={mode:'code',modes:{code:{view:'chat',session:'desktop',panel:'overview'},chat:{view:'today',session:'research',panel:null}},theme:'light',offline:false,mini:false,tab:'Outputs',support:'on',quiet:true,stream:false,completed:false,runState:'unverified',notes:[],attachments:[],queue:[],queueRevision:0,schedulePaused:false,workerPaused:false,connectorEnabled:true,skillEnabled:true,model:'Auto · balanced',permission:'plan',effort:'Medium',captured:[],tasks:{desktop:{title:'A better Vanta desktop',project:'Vanta',mode:'code',draft:'',messages:[]},tests:{title:'Review the runtime changes',project:'Vanta',mode:'code',draft:'',messages:[]},research:{title:'Research for the next release',project:'Vanta',mode:'chat',draft:'',messages:[]},week:{title:'Make space for this week',project:'Personal',mode:'chat',draft:'',messages:[]}},receipt:null};
let state=structuredClone(initial);try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.tasks?.desktop&&saved?.modes?.code)state={...state,...saved,offline:false,mini:false}}catch{}
state.profiles??=['Default','Research','Personal'];state.profile??='Default';state.workerTab??='Workers';state.customSchedules??=[];state.memoryText??='Prefer a plan before application changes.';state.memoryArchived??=false;state.voiceEnabled??=false;state.wakeEnabled??=false;
const runTimers=new Map();let timer=null,dialogOpener=null,toastTimer=null; let currentPanelFile='REDESIGN-PLAN.md';
const m=()=>state.modes[state.mode];const task=()=>state.tasks[m().session];const attachments=()=>task().attachments??(task().attachments=[]);const queue=()=>task().queue??(task().queue=[]);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{announce('Browser storage is unavailable. This window still works, but reload may lose changes.')}}
function announce(text){$('#announcement').textContent=text}
function toast(text){$('#toast').hidden=false;$('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);announce(text)}
function fillIcons(){ $$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon)) }
function btn(label,action,primary=false,extra=''){return `<button class="btn${primary?' primary':''}" data-action="${action}" ${extra}>${label}</button>`}
function setView(view){$('#app').classList.remove('sidebar-mobile');m().view=view;save();render();$('#content').focus()}
function openTask(id){$('#app').classList.remove('sidebar-mobile');const original=state.tasks[id];if(original.profile!==state.profile){const scoped='scoped-'+state.profile+'-'+id;if(!state.tasks[scoped])state.tasks[scoped]={title:'New conversation',project:state.profile,profile:state.profile,mode:original.mode,draft:'',messages:[],runState:'unverified',completed:false};id=scoped;}m().session=id;m().view='chat';save();render();$('#content').focus()}
function switchMode(mode){$('#app').classList.remove('sidebar-mobile');if(mode===state.mode)return;state.mode=mode;state.tab='Outputs';save();render();announce(`${mode==='code'?'Code':'Chat'} mode. Saved session and draft restored. Permissions unchanged.`)}
function row(symbol,title,body,control='',tag=''){return `<div class="row"><span class="row-icon">${icon(symbol)}</span><div class="row-copy"><strong>${title}</strong><p>${body}</p></div>${tag?`<span class="tag">${tag}</span>`:''}${control}</div>`}
function heading(title,subtitle,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
function outputCard(){return `<button class="output-card" data-panel="outputs"><span class="file-icon">${icon('file')}</span><span><strong>Desktop direction.md</strong><small>Sample output · Markdown · ready for review</small></span><span>↗</span></button>`}
function currentStatus(){if(state.offline)return ['Offline','pending'];if(task().runState==='needs human')return ['Needs you','pending'];if(task().runState==='running')return ['Running',''];if(task().runState==='stopped')return ['Stopped',''];if(task().runState==='verified')return ['Verified · sample',''];return ['Ready for review','']}
function render(){
 state.profiles??=['Default','Research','Personal'];state.profile??='Default';state.customSchedules??=[];state.workerTab??='Workers';state.profileStates??={};
 for(const t of Object.values(state.tasks)){t.profile??='Default';t.runState??='unverified';t.completed??=false;}
 document.documentElement.dataset.theme=state.theme;$('#app').classList.toggle('mini',state.mini);
 $$('.mode-switch button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode)));
 $$('.primary [data-view]').forEach(b=>m().view===b.dataset.view?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current'));
 const groups={};Object.entries(state.tasks).filter(([,t])=>t.mode===state.mode&&t.profile===state.profile&&!t.archived).sort((a,b)=>Number(Boolean(b[1].pinned))-Number(Boolean(a[1].pinned))).forEach(([id,t])=>(groups[t.project]??=[]).push([id,t]));
 $('#projects').innerHTML=Object.entries(groups).map(([group,ts])=>`<section class="project-group"><div class="project-header"><button class="project-name" data-action="project">${esc(group)}</button><button class="icon-btn" data-action="new" aria-label="New conversation in ${esc(group)}">＋</button></div>${ts.map(([id,t])=>`<button class="session${task().runState==='needs human'&&id==='desktop'?' pending':''}" data-task="${id}" ${m().view==='chat'&&m().session===id?'aria-current="page"':''}><span class="session-symbol">${t.runState==='running'?'◉':t.runState==='needs human'?'◇':'○'}</span><span class="session-name">${esc(t.title)}</span></button><button class="session-menu-button" data-session-menu="${id}" aria-label="Options for ${esc(t.title)}">···</button>`).join('')}</section>`).join('');
 const titles={today:'Today',automations:'Automations',library:'Library',connections:'Connections',settings:'Settings',features:'Feature preservation',profiles:'Profiles',workers:'Workers & budgets',skills:'Skills & tools'};
 $('#title').textContent=m().view==='chat'?task().title:titles[m().view]||'Vanta';$('#project-label').textContent=m().view==='chat'?task().project:'Personal workspace';
 const [status,cls]=currentStatus();$('#run-status').textContent=status;$('#run-status').className='status '+cls;$('#run-status').hidden=m().view!=='chat';
 $('#needs-count').textContent=task().runState==='needs human'?'1':task().completed?'0':'1';
 $('#connection-banner').hidden=!state.offline;$('#connection-banner').innerHTML='Runtime offline. Your draft is saved. No queued message will run on reconnect. <button data-action="network">Reconnect sample runtime</button>';
 $('#profile-label').innerHTML=esc(state.profile)+'<small>Local profile</small>';$('#profile-initial').textContent=state.profile.charAt(0).toUpperCase();
 $('#connection-text').textContent=state.offline?'Offline · drafts saved':'Local runtime · simulated';$('#network-toggle').textContent=state.offline?'Reconnect':'Test offline';
 const main=$('#content');main.className=m().view==='chat'?'chat-main':'';
 const views={chat:chatView,today:todayView,automations:automationView,library:libraryView,connections:connectionsView,settings:settingsView,workers:workersView,skills:skillsView,features:featuresView,profiles:profilesView};
 main.innerHTML=(views[m().view]||chatView)();reframeComposer();renderPanel();restoreCards();fillIcons();save();
}
function chatView(){
 const t=task();const isCode=state.mode==='code';const isNew=!['desktop','tests','research','week'].includes(m().session);
 let body=t.messages.length?t.messages.map(x=>`<article class="message ${x.role==='user'?'user':''}"><div class="speaker">${x.role==='user'?'You':'Vanta'}</div><p>${esc(x.text)}</p></article>`).join(''):
 isNew?`<div class="new-chat-welcome"><span class="welcome-mark">V</span><h1>${isCode?'What are we building?':'What can I help you with?'}</h1><p>${isCode?'Work in the selected project, with your permissions in view.':'Research, plan, write, or take the next step.'}</p><div class="starter-prompts"><button data-starter="Prepare a plan before making changes.">Prepare a plan</button><button data-starter="Review the current project and explain what needs attention.">Review a project</button><button data-starter="Help me pick up where I left off.">Pick up where I left off</button></div></div>`:isCode?`<article class="message user"><p>Use Claude’s Chat and Code workflow for Vanta. Keep the features we already have, and let me review the design before changing the app.</p></article><article class="message"><div class="speaker"><span class="brand-mark" style="width:20px;height:20px;font-size:12px">V</span>Vanta</div><p>One desktop app, with <strong>Chat and Code</strong> side by side.</p><p>Chat stays open for research, planning, and the rest of your work. Code brings the repository, changes, and terminal into focus. Your projects and outputs stay connected.</p><details class="tool-summary"><summary>Inspected the desktop shell and preservation inventory</summary><p>Sample activity: read interface contracts → compare navigation → map the existing capabilities. No live tool calls in this prototype.</p></details><p>I’ve kept the runtime, model routing, memory, skills, approvals, schedules, and worker capabilities. The change is how you reach and supervise them.</p><details class="inline-plan-card"><summary><span>Plan</span><small>2 of 4 steps</small></summary><ol class="steps"><li class="done"><span>✓</span>Inspect existing features</li><li class="done"><span>✓</span>Compare Claude workflows</li><li><span>◉</span>Review the desktop design</li><li><span>○</span>Authorize application changes</li></ol></details><button class="inline-change-card" data-panel="changes">${icon('diff')}<span>Proposed shell changes<small>Sample diff · no application edits</small></span><span>+3 −1 ↗</span></button>${outputCard()}<div class="reentry"><strong>Where we left off</strong><br>The design is prepared. Next: review the layout and the preservation map. Application changes haven’t started.</div></article>`:
 `<article class="message user"><p>Help me prepare the next release. Keep the research and the coding work connected.</p></article><article class="message"><div class="speaker">Vanta</div><p>Let’s keep the outcome in one place. I can gather the research here, prepare a brief, and hand a clearly scoped task to Code when you’re ready.</p><p>Nothing needs to run yet. Your notes, open questions, and the next step will still be here when you return.</p><details class="inline-plan-card"><summary><span>Plan</span><small>2 of 4 steps</small></summary><ol class="steps"><li class="done"><span>✓</span>Inspect existing features</li><li class="done"><span>✓</span>Compare Claude workflows</li><li><span>◉</span>Review the desktop design</li><li><span>○</span>Authorize application changes</li></ol></details><button class="inline-change-card" data-panel="changes">${icon('diff')}<span>Proposed shell changes<small>Sample diff · no application edits</small></span><span>+3 −1 ↗</span></button>${outputCard()}<div class="reentry"><strong>Next step</strong><br>Review the prepared brief, or open the task in Code with the context you choose.</div><button class="btn" data-action="handoff">Open this task in Code →</button></article>`;
 if(task().runState==='running')body+=`<div class="demo-run" role="status"><span>◉ &nbsp;Reading the sample project…</span><button data-action="stop">Stop</button></div>`;
 if(task().runState==='needs human')body+=`<div class="callout attention"><h3>Vanta needs your approval</h3><p>Write one sample file in this project. Review the exact action before continuing.</p>${btn('Review action','approval',true)}</div>`;
 if(task().runState==='unverified'&&task().completed)body+=`<div class="callout"><h3>Result prepared · unverified</h3><p>The sample run ended. Its output has not been checked against the task’s Done criterion.</p>${btn('Verify sample result','verify',true)}</div>`;
 if(task().runState==='verified')body+=`<div class="callout"><h3>✓ Verified · sample</h3><p>Sample readback matches the expected file and content. This demonstrates the receipt UI; it does not verify Vanta’s runtime.</p>${btn('View receipt','receipt')}</div>`;
 if(task().runState==='stopped')body+=`<div class="callout"><h3>Stopped. Your work is still here.</h3><p>Partial output and the next step are preserved. Nothing will restart automatically.</p><div class="actions">${btn('Resume sample','run')}${btn('Edit request','focus')}</div></div>`;
 const queueMarkup=queue().length?`<div class="queued"><div class="queue-head"><strong>Saved next · ${queue().length}</strong><button data-action="run-queue">Run next</button></div>${queue().map((q,i)=>`<div class="queue-row"><span>${esc(q)}</span><button data-q="${i}" data-queue="edit" aria-label="Edit queued message ${i+1}">Edit</button><button data-q="${i}" data-queue="up" aria-label="Move queued message ${i+1} earlier" ${i===0?'disabled':''}>↑</button><button data-q="${i}" data-queue="remove" aria-label="Remove queued message ${i+1}">×</button></div>`).join('')}</div>`:'';
 return `${!isNew?'<h1 class="sr">'+esc(t.title)+'</h1>':''}<div class="thread" id="thread" aria-label="Conversation">${body}</div><div class="composer-wrap">${queueMarkup}<form id="composer-form" class="composer"><div class="attachments">${attachments().map((a,i)=>`<span class="attachment">${esc(a)}<button type="button" data-remove="${i}" aria-label="Remove ${esc(a)}">×</button></span>`).join('')}</div><label class="sr" for="prompt">Message Vanta in ${isCode?'Code':'Chat'}</label><textarea id="prompt" placeholder="${isCode?'Ask Vanta about this project…':'What would you like to work on?'}">${esc(t.draft)}</textarea><div class="composer-controls"><button type="button" class="icon-btn" data-action="attach" aria-label="Attach context">${icon('plus')}</button><button type="button" class="icon-btn" data-action="voice" aria-label="Voice and capture options">${icon('mic')}</button><label class="sr" for="model">Model route</label><select id="model">${['Auto · balanced','Local model · sample','Choose a provider…'].map(v=>`<option ${state.model===v?'selected':''}>${v}</option>`).join('')}</select><label class="sr" for="effort">Effort</label><select id="effort">${['Low','Medium','High','Max'].map(v=>`<option ${state.effort===v?'selected':''}>${v}</option>`).join('')}</select><label class="sr" for="permission">Permission mode</label><select id="permission">${[['plan','Plan'],['manual','Manual'],['acceptEdits','Accept edits'],['auto','Auto'],['fullAccess','Full access…']].map(([v,l])=>`<option value="${v}" ${state.permission===v?'selected':''}>${l}</option>`).join('')}</select><button class="send" type="${task().runState==='running'?'button':'submit'}" ${task().runState==='running'?'data-action="stop"':''} aria-label="${task().runState==='running'?'Stop sample run':'Send sample message'}">${task().runState==='running'?'■':'↑'}</button></div></form><div class="composer-caption">${state.permission==='plan'?'Plan is read-only. ':''}Enter to send · Shift Enter for a new line · sample responses only</div></div>`;
}
function todayView(){if(state.support!=='on')return `<div class="page">${heading('Today','Your work stays available. Optional support is off.')}<div class="callout"><h2>Support is ${esc(state.support)}</h2><p>No recommendations or repeated nudges are shown here.</p><div class="actions">${btn('Turn support on','support-on',true)}${btn('Open conversation','open-chat')}</div></div></div>`;return `<div class="page">${heading('Pick up where you left off.','One operator, across your work and life.',btn('New conversation','new'))}<form class="capture" id="capture-form"><label class="sr" for="capture">What do you want off your mind?</label><input id="capture" placeholder="Drop the messy version here. No category needed."><button class="btn primary">Capture</button></form>${state.captured.map((s,i)=>row('file',esc(s),'Captured · private sample draft',btn('Open','captured',false,'data-capture-index="'+i+'"'),'Draft')).join('')}<section class="section"><div class="section-title"><h2>Needs you</h2><span>${task().completed?'Nothing urgent':'One decision'}</span></div>${task().completed?'<p class="muted small">Nothing needs your attention.</p>':`<div class="callout attention"><h3>Review the desktop direction</h3><p>The plan is prepared. You can review it without starting implementation.</p><div class="actions">${btn('Review plan','review',true)}${btn('Snooze','snooze')}${btn('Skip','skip')}</div></div>`}</section><section class="section"><div class="section-title"><h2>Continue</h2><span>Your context is saved</span></div>${row('folder','A better Vanta desktop','Last step: compared the existing features. Next: review the Chat / Code layout.',btn('Resume in Code','resume'))}${row('file','Research for the next release','Brief prepared. No messages sent and no external changes made.',btn('Open in Chat','open-chat'))}</section><section class="section"><div class="section-title"><h2>Coming up</h2><span>Quiet unless something changes</span></div>${row('clock','Morning orientation','Tomorrow · 09:00 Europe/Madrid · this Mac must be awake',btn('View','automations'),'Scheduled')}</section><section class="section"><div class="section-title"><h2>Recent outputs</h2><button class="btn text" data-view="library">View library →</button></div>${outputCard()}</section><details class="small muted"><summary>Support preferences</summary><p style="margin-top:12px">Capacity stays unknown unless you choose to share it. Seven dimensions remain available in the full design.</p><div class="support-controls"><label for="support">Today support</label><select id="support">${['on','off for this session','off for this pattern','off everywhere'].map(x=>`<option ${state.support===x?'selected':''}>${x}</option>`).join('')}</select></div></details></div>`}
function automationView(){return `<div class="page">${heading('Automations','Schedules and monitors, with visible boundaries.',btn('Prepare automation','new-automation',true))}<p class="small muted">Sample schedules. Nothing here runs against a real account.</p>${row('clock','Morning orientation',`${state.schedulePaused?'Paused':'Next: tomorrow at 09:00'} · Europe/Madrid · local Mac`,btn(state.schedulePaused?'Resume':'Pause','schedule-toggle'),state.schedulePaused?'Paused':'Scheduled')}${row('search','Watch the release checks','Last checked 14 minutes ago · no change · notify only on a result',btn('Review scope','automation-scope'),'Waiting')}<section class="section"><h2>When this Mac sleeps</h2><p class="muted small">Local jobs don’t run while the host is asleep. On return, Vanta shows what was missed and asks before replaying an action that may have happened.</p><div class="callout"><h3>One wake was missed</h3><p>Sample: orientation was due while this Mac was offline. No action was taken.</p>${btn('Review missed wake','missed')}</div></section></div>`}
function tabs(names){return `<div class="subnav" role="group" aria-label="Library sections">${names.map(t=>`<button data-tab="${t}" aria-pressed="${state.tab===t}">${t}</button>`).join('')}</div>`}
function libraryView(){let content='';if(state.tab==='Runs')content=`${row('clock','Desktop direction review','Prepared output · unverified · sample run',btn('Use as new task','reuse'),'Saved')}${row('diff','Runtime regression review','Stopped at checkpoint · partial result preserved',btn('Recovery options','recovery'),'Stopped')}`;
 else if(state.tab==='Memory')content=`<div class="callout"><h3>Memory you can inspect and correct</h3><p>Every memory keeps its source, scope, last review, and expiry. A preference is not an identity.</p></div>${row('file',esc(state.memoryText||'Prefer a plan before application changes.')+(state.memoryArchived?' (archived)':''),'Source: explicit preference · scope: this sample project · review any time',btn('Inspect / edit','memory'),'User-stated')}${row('folder','Project context','Files and project instructions remain distinct from personal memory.',btn('Open project context','context'))}`;
 else if(state.tab==='Skills')content=skillsContent();
 else content=`<input class="search-input" id="library-search" aria-label="Search outputs" placeholder="Search outputs…"><div data-searchable="desktop direction">${row('file','Desktop direction.md','Vanta · Markdown · sample output',btn('Open','output'))}</div><div data-searchable="release brief">${row('file','Release brief.md','Research · Markdown · sample output',btn('Open','output'))}</div><div data-searchable="canvas release checks">${row('panel','Release checks','Sample chart · table and board views available',btn('Open canvas','canvas'))}</div>`;
 return `<div class="page">${heading('Library','Outputs, reusable runs, memory, and capabilities.')} ${tabs(['Outputs','Runs','Memory','Skills'])}${content}</div>`}
function skillsContent(){return `<input class="search-input" id="library-search" aria-label="Search skills" placeholder="Search skills and tools…"><div data-searchable="research source">${row('search','Research with sources','Installed · available in Chat and Code · preview before use',btn('Preview','skill'),'Installed')}</div><div data-searchable="code review">${row('diff','Code review','Installed · scope: selected repository',btn(state.skillEnabled?'Enabled':'Disabled','skill-toggle'),state.skillEnabled?'Enabled':'Off')}</div><section class="section"><h2>Find more skills</h2><p class="muted small">Search skills.sh or GitHub, inspect the source and risk preview, then approve an install. No package is installed by this prototype.</p>${btn('Preview a sample install','skill-install')}</section>`}
function skillsView(){return `<div class="page">${heading('Skills & tools','Capability stays available without crowding the conversation.')}${skillsContent()}</div>`}
function connectionsView(){return `<div class="page">${heading('Connections','Accounts, local MCP servers, and messaging in one place.',btn('Add connection','add-connection'))}<p class="small muted">Connection states below are examples, not your real accounts.</p>${row('link','GitHub','Remote connector · read repository metadata · sample only',btn('Inspect scope','connector'),'Connected')}${row('folder','Project files','Local capability · selected project only',btn(state.connectorEnabled?'Turn off':'Turn on','connector-toggle'),state.connectorEnabled?'On':'Off')}${row('link','Telegram','Messaging gateway · pairing and approval required',btn('Setup preview','messaging'),'Not connected')}${row('link','Google Workspace','Provider setup and consent remain explicit; no credentials migrate.',btn('Setup preview','google'),'Not connected')}<section class="section"><h2>Local and remote are different</h2><p class="muted small">Local tools depend on this Mac. Remote connectors depend on their service and account. Each shows where it runs and what it can access.</p></section></div>`}
function workersView(){return `<div class="page">${heading('Workers & budgets','The existing Company capabilities, kept in an advanced view.',btn('Prepare worker','new-worker'))}<div class="subnav"><button aria-pressed="true">Workers</button><button data-action="tickets">Tickets</button><button data-action="budget">Budgets</button><button data-action="activity">Activity</button></div>${row('terminal','Release reviewer',`${state.workerPaused?'Pause requested — waiting for checkpoint':'Native Vanta loop · bounded read-only review'} · sample`,btn(state.workerPaused?'View checkpoint':'Request pause','worker-pause'),state.workerPaused?'Pause requested':'Running')}<section class="section"><h2>Budget</h2><div class="progress-track"><span></span></div><p class="small muted">Sample estimate: 48% of a demonstration budget. Actual provider cost: not reported.</p>${btn('Review scope and budget','budget')}</section><div class="callout"><h3>One operator, bounded help</h3><p>Workers keep explicit targets, deadlines, spending limits, and receipts. Hiring and external CLI execution still require the appropriate authority.</p></div></div>`}
function settingsView(){return `<div class="page">${heading('Settings','Preferences stay scoped. Your work stays intact.')}<section class="settings-group"><h2>Appearance & workspace</h2><div class="setting"><label for="theme">Theme<small>Neutral Vanta surfaces, with violet for focus.</small></label><select id="theme"><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option></select></div><div class="setting"><span>Compact window<small class="label">Composer and live result over other apps.</small></span>${btn('Preview compact','mini')}</div><div class="setting"><span>Advanced layout tools<small class="label">Splits, saved layouts, pane swapping, detached windows.</small></span>${btn('Explore layout','layouts')}</div></section><section class="settings-group"><h2>Models & connections</h2>${row('link','Providers and model routing','Existing API keys, local model support, effort, speed, and recovery remain.',btn('Configure preview','providers'))}${row('folder','Runtime profiles','Create, clone, import, export, select. Authority is never restored by import.',btn('Profile options','profiles'))}</section><section class="settings-group"><h2>Attention & continuity</h2><div class="setting"><label for="quiet">Quiet hours<small>Notify only for meaningful changes or decisions.</small></label><input type="checkbox" id="quiet" ${state.quiet?'checked':''}></div><div class="setting"><label for="stream">Follow the response<small>Off keeps your reading position stable.</small></label><input type="checkbox" id="stream" ${state.stream?'checked':''}></div>${btn('Voice, wake word & capture','voice')}</section><section class="settings-group"><h2>Trust & data</h2>${row('check','Permissions and receipts','Current sample mode: '+esc(state.permission)+'. The kernel can still block actions.',btn('Inspect authority','authority'))}<p class="small muted">Export, archive, reset, API access, LAN companion, signing and updates remain in the full implementation plan.</p>${btn('Reset prototype sample data','reset')}<p class="keyboard-note">This resets this prototype only. It does not touch Vanta.</p></section></div>`}
function renderPanel(){
 const p=m().view==='chat'?m().panel:null;const pane=$('#inspector');pane.classList.toggle('open',Boolean(p));$$('.pane-buttons button').forEach(b=>b.setAttribute('aria-pressed',String(p===b.dataset.panel)));
 if(!p){pane.innerHTML='';return}const names={overview:'Task context',files:'Files',changes:'Changes',terminal:'Terminal',browser:'Browser',outputs:'Output'};
 let body='';
 if(p==='overview')body=`<details class="rail-card" open><summary>Environment</summary><div class="rail-body"><div class="env-line">${icon('terminal')}<span>${esc(state.profile)} profile</span></div><div class="env-line">${icon('folder')}<span>${esc(task().project)}</span><small>Selected project</small></div><div class="env-line">${icon('diff')}<span>working copy</span><small>Sample</small></div><div class="env-line">${icon('check')}<span>${esc(state.permission)}</span><small>Kernel enforced</small></div></div></details><details class="rail-card"><summary>Context <small>18% · sample</small></summary><div class="rail-body"><p class="small muted">Context stays scoped to this project and profile.</p><button class="file-row" data-file="FEATURE-PRESERVATION.csv">${icon('file')}Feature preservation<small>296 entries</small></button><button class="file-row" data-file="REDESIGN-PLAN.md">${icon('file')}Redesign plan</button><button class="btn" data-action="features">Inspect full preservation map</button></div></details><details class="rail-card"><summary>Connections <small>3 available · sample</small></summary><div class="rail-body"><p class="small muted">Project files · local<br>GitHub · remote<br>Browser · local</p>${btn('Manage connections','connections')}</div></details><details class="rail-card" open><summary>Outputs</summary><div class="rail-body"><button class="file-row" data-panel="outputs">${icon('file')}Desktop direction.md<small>Markdown</small></button><button class="file-row" data-action="canvas">${icon('panel')}Release checks<small>Canvas</small></button><button class="file-row" data-view="library">${icon('library')}View all outputs</button></div></details><details class="rail-card"><summary>Plan <small>2 of 4 · sample</small></summary><div class="rail-body"><ol class="steps"><li class="done"><span class="step-symbol">✓</span>Inspect current capabilities</li><li class="done"><span class="step-symbol">✓</span>Compare reference workflows</li><li class="current"><span class="step-symbol">◉</span>Review the experience</li><li><span class="step-symbol">○</span>Authorize implementation</li></ol><p class="small muted">Next safe step: review the design.</p></div></details><details class="rail-card"><summary>Changes <small>Proposed only</small></summary><div class="rail-body"><button class="file-row" data-panel="changes">${icon('diff')}Review sample change<small>+3 −1</small></button></div></details><details class="rail-card" open><summary>Background tasks <small>Sample run controls</small></summary><div class="rail-body"><p class="small muted">Try Stop, a scoped approval, and a result receipt. No live execution.</p>${btn('Start sample run','run')}<p class="permission-description">Plan prepares only. Manual enables the sample approval path.</p>${btn('Workers & budgets','workers')}</div></details>`;
 if(p==='files')body=`<span class="label">${esc(task().project)} · sample tree</span>${['REDESIGN-PLAN.md','FEATURE-PRESERVATION.csv','desktop/shell.tsx','desktop/navigation.ts','README.md'].map(f=>`<button class="file-row" data-file="${f}">${icon('file')}${f}</button>`).join('')}<div class="preview-paper"><strong>${esc(currentPanelFile)}</strong><p class="small muted">Read-only sample preview.</p><p>Chat and Code share one Vanta Engine. Each mode preserves its session, draft, and workspace.</p><button class="btn" data-action="attach-file">Attach as context</button></div>`;
 if(p==='changes')body=`<p class="small muted">Proposed sample change · no repository files changed.</p><button class="file-row" data-file="desktop/shell.tsx">${icon('diff')}desktop/shell.tsx<small>+3 −1</small></button><div class="code-block">  &lt;Workspace&gt;\n<span class="diff-add">+   &lt;ModeSwitch modes={["Chat", "Code"]} /&gt;\n+   &lt;ProjectSessions scope={workspace} /&gt;\n+   &lt;Workbench openOnUserIntent /&gt;</span>\n  &lt;/Workspace&gt;</div><label class="label" for="diff-note">Review comment</label><textarea id="diff-note" rows="3" placeholder="Leave a sample review comment…"></textarea><div class="actions" style="margin-top:10px">${btn('Save review comment','save-comment')}</div>${state.notes.map(n=>`<p class="small" style="margin-top:14px">◌ ${esc(n)}</p>`).join('')}`;
 if(p==='terminal')body=`<p class="small muted">Sandboxed demonstration · no shell access</p><div class="code-block">$ git status --short\n  sample workspace: no real files touched\n\n$ check-preservation\n  296 inventory entries mapped\n  runtime validation: not executed</div><label class="label" for="terminal-input">Sample terminal command</label><input id="terminal-input" placeholder="Try: help" style="width:100%"><div class="actions" style="margin-top:10px">${btn('Run sample command','terminal-command')}</div><div id="terminal-result" class="code-block" hidden></div>`;
 if(p==='browser')body=`<div class="tag">Local preview · isolated sample</div><div class="preview-paper"><h2>Vanta</h2><p>One operator.<br>Chat and Code, together.</p><p class="muted small">A preview belongs next to the work that produced it.</p></div><p class="small muted">The real implementation keeps browser content isolated from native capabilities. This prototype does not browse external sites.</p>${btn('Refresh sample preview','refresh-preview')}`;
 if(p==='outputs')body=`<span class="label">Markdown · sample output</span><div class="preview-paper"><h2>Desktop direction</h2><p><strong>One app. Two ways to work.</strong></p><p>Chat handles the general work of life. Code brings a repository and its tools into focus.</p><ul><li>Shared projects and outputs</li><li>Drafts and re-entry preserved</li><li>Visible authority and receipts</li><li>Local-first continuity</li></ul><p>Preserve the engine. Redesign the experience.</p></div><div class="output-tools">${btn('Copy text','copy-output')}${btn('Save sample file','download')}</div><h3>Verification</h3><p class="small muted">${task().runState==='verified'?'Sample receipt verified. The live runtime is not connected.':'Prepared for review. This is not a verified runtime result.'}</p>`;
 pane.innerHTML=`<div class="inspector-head"><strong>${names[p]}</strong><button class="icon-btn" data-action="close-panel" aria-label="Close workbench">×</button></div>${body}`;
}
function modal(title,body,actions=''){dialogOpener=document.activeElement;$('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">×</button></div>${body}${actions?`<div class="actions">${actions}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal();fillIcons()}
function closeModal(){if($('#dialog').open)$('#dialog').close();if(dialogOpener?.isConnected)dialogOpener.focus()}
function approval(){modal('Review the exact action',`<span class="tag">Sample approval · one use only</span><p style="margin-top:18px">Write <strong>Desktop direction.md</strong> into the sample project.</p><div class="code-block">tool: write_file\nproject: Vanta (sample)\ntarget: /sample/vanta/Desktop direction.md\neffect: create one local sample file\nnetwork: none\nbudget: no paid service\nexpires: when this preview changes</div><p>Allow once does not grant recurring authority. A changed target, content, or project needs a new preview.</p>${state.permission==='plan'?'<p class="error">Plan mode is read-only. Choose Manual in the composer to try the simulated approval flow.</p>':''}`,btn('Allow once','allow',true,state.permission==='plan'?'disabled':'')+btn('Deny','deny')+btn('Back','close-dialog'))}
function simulate(){const owner=task(),ownerId=m().session,permission=state.permission;if(state.offline){toast('Offline. Your draft is saved; reconnect before starting a sample run.');return}if(owner.runState==='running'){toast('The sample run is already running.');return}owner.runState='running';owner.completed=false;save();render();announce('Sample run started. Stop remains available.');clearTimeout(runTimers.get(ownerId));runTimers.set(ownerId,setTimeout(()=>{if(owner.runState!=='running')return;owner.runState=permission==='plan'?'unverified':'needs human';if(permission==='plan')owner.completed=true;save();render();announce(permission==='plan'?'Plan prepared. No file was written.':'Sample action is waiting for your approval.');},2200))}
function send(){const input=$('#prompt');const text=input.value.trim();if(!text){announce('Enter a message first.');input.focus();return}task().draft='';if(state.offline||task().runState==='running'||task().runState==='needs human'){queue().push(text);state.queueRevision++;save();render();toast('Saved in the sample queue. It will not run automatically.');return}task().messages.push({role:'user',text});task().messages.push({role:'assistant',text:'Sample response: I’ve kept your request in this task. In the full app, Vanta Engine would handle the model, tools, and permissions. Open Task context to exercise a simulated run.'});save();render();announce('Sample response added. No model service was contacted.')}
function outputText(){return state.selectedOutput==='brief'?'# Release research brief\n\nSample document prepared in Chat. Outcome: decide the next release scope. Evidence: separate inspected source, documented behavior, and runtime gaps. Next step: hand a scoped draft to Code after review.':'# Vanta desktop direction\n\nPrototype sample output. One app: Chat and Code. Shared projects and outputs, scoped authority.'}
function reuse(){closeModal();state.mode='code';openTask('desktop');task().draft='Use the prepared desktop direction as a new task. Review scope before starting.';save();render();$('#prompt')?.focus()}
const actions={
 sidebar:()=>{if(matchMedia('(max-width:820px)').matches)$('#app').classList.toggle('sidebar-mobile');else $('#app').classList.toggle('sidebar-hidden')},
 new:()=>{const id='task-'+Date.now();state.tasks[id]={title:'New conversation',project:state.mode==='code'?'Vanta':'Personal',mode:state.mode,profile:state.profile,draft:'',messages:[]};m().session=id;m().view='chat';save();render();$('#prompt').focus()},
 search:()=>{modal('Search your workspace','<label for="global-search">Find a conversation, project, or command</label><input id="global-search" placeholder="Search…" autocomplete="off"><div class="menu-list" id="search-results"></div>');searchResults('');$('#global-search').focus()},
 more:()=>modal('More','<div class="menu-list"><button data-view="today">'+icon('home')+'Today<span>Continuity</span></button><button data-view="automations">'+icon('clock')+'Automations<span>Schedules & workflows</span></button><button data-view="connections">'+icon('link')+'Connections<span>MCP & messaging</span></button><button data-view="workers">'+icon('terminal')+'Workers & budgets<span>Company</span></button><button data-view="profiles">'+icon('folder')+'Profiles<span>Local profiles</span></button><button data-view="settings">'+icon('settings')+'Settings<span>⌘,</span></button></div>'),
 project:()=>modal('Projects stay connected','<p>Chat and Code use the same project identity, while conversation context stays scoped. Switching views never grants access to a new directory.</p><div class="menu-list"><button data-action="resume">Vanta<span>Code workspace</span></button><button data-action="open-chat">Research<span>Chat workspace</span></button><button data-action="profiles">Manage projects and profiles<span>Advanced</span></button></div>'),
 'view-options':()=>modal('View options','<div class="menu-list"><button data-panel="overview">Task context<span>Outcome & next step</span></button><button data-action="layouts">Workspace layouts<span>Advanced</span></button><button data-action="mini">Compact window<span>Preview</span></button></div>'),
 'close-dialog':closeModal,'close-panel':()=>{m().panel=null;save();render()},focus:()=>$('#prompt')?.focus(),
 run:simulate,stop:()=>{clearTimeout(runTimers.get(m().session));runTimers.delete(m().session);task().runState='stopped';save();render();announce('Stopped. No automatic retry. Partial output and queue preserved.')},
 approval,allow:()=>{closeModal();task().completed=true;task().runState='unverified';task().receipt={action:'write_file',target:'/sample/vanta/Desktop direction.md',authority:'One-use sample approval',status:'unverified'};save();render();announce('Sample action ended. Result remains unverified.')},
 deny:()=>{closeModal();clearTimeout(timer);task().runState='stopped';task().receipt={status:'denied',action:'write_file'};save();render();toast('Denied. No sample action was performed.')},
 verify:()=>{task().runState='verified';task().completed=true;task().receipt={status:'verified',action:'write_file',target:'/sample/vanta/Desktop direction.md',evidence:'Simulated readback matches expected sample content',scope:'Prototype only; not a live engine receipt'};save();render();announce('Sample readback verified. This is a demonstration receipt only.')},
 receipt:()=>modal('Sample receipt',`<pre class="code-block">${esc(JSON.stringify(task().receipt,null,2))}</pre><p>This receipt describes a simulated result. Native Vanta acceptance is a separate gate.</p>`),
 'run-queue':()=>{if(state.offline||task().runState==='running'||task().runState==='needs human'){toast('Resolve the current run or reconnect first. The queue is preserved.');return}const text=queue().shift();if(text){task().draft=text;state.queueRevision++;save();render();$('#prompt').focus();toast('Restored as a draft. Review it before sending.')}},
 attach:()=>modal('Add context','<div class="menu-list"><button data-action="attach-sample">'+icon('file')+'Sample project file<span>No upload</span></button><button data-action="pick-file">'+icon('folder')+'Choose a local file<span>Filename only</span></button><button data-action="capture-preview">'+icon('panel')+'Capture selection, window, or screen<span>Preview only</span></button></div>'),
 'attach-sample':()=>{attachments().push('FEATURE-PRESERVATION.csv');closeModal();save();render()},
 'pick-file':()=>{const input=document.createElement('input');input.type='file';input.onchange=()=>{const file=input.files[0];if(file){attachments().push(file.name+' (name only)');closeModal();save();render()}};input.click()},
 'capture-preview':()=>modal('Capture context','<p>The full app keeps selection, window, and screen capture, with OS permission and cancel recovery. This prototype does not capture your screen.</p>',btn('Attach sample screenshot','attach-capture',true)),
 'attach-capture':()=>{attachments().push('sample-screen.png');closeModal();save();render()},
 'attach-file':()=>{attachments().push(currentPanelFile);save();render();toast('Sample file attached as context.')},
 voice:()=>modal('Voice & capture','<p>Keep local Whisper dictation, wake word, playback, and screen capture. Each retains a visible permission state.</p><div class="menu-list"><button data-action="voice-sample">'+icon('mic')+'Try sample dictation<span>No microphone access</span></button><button data-action="wake">Wake word: Hey Vanta<span>Setup preview</span></button><button data-action="capture-preview">Capture screen context<span>Preview</span></button></div>'),
 'voice-sample':()=>{closeModal();if(m().view!=='chat')m().view='chat';task().draft='Sample dictation: help me prepare the next release.';save();render();$('#prompt').focus()},
 wake:()=>modal('Wake word','<p>“Hey Vanta” remains an opt-in local capability. The real app must show mic permission, listening state, and an immediate Off control. No microphone permission is requested here.</p>'),
 review:()=>{closeModal();state.mode='code';openTask('desktop');m().panel='outputs';save();render()},resume:()=>{closeModal();state.mode='code';openTask('desktop')},'open-chat':()=>{closeModal();state.mode='chat';openTask('research')},
 snooze:()=>{task().completed=true;save();render();toast('Sample review snoozed. You can resume it from Projects.')},skip:()=>{task().completed=true;save();render();toast('Skipped for this sample session. No repeated nudge.')},captured:button=>{const text=state.captured[Number(button.dataset.captureIndex)];if(!text)return;const id='capture-'+Date.now();state.tasks[id]={title:text.slice(0,50),project:state.profile,profile:state.profile,mode:'chat',draft:text,messages:[]};state.mode='chat';openTask(id)},
 handoff:()=>modal('Open this task in Code','<p>Prepare a draft in the selected repository. The current Chat conversation stays intact.</p><label for="handoff-context"><input type="checkbox" id="handoff-context" checked> Include the sample brief and the explicit next step</label><p class="small muted">No credentials, permissions, or standing grants transfer.</p>',btn('Prepare Code draft','handoff-confirm',true)),
 'handoff-confirm':()=>{const include=$('#handoff-context').checked;closeModal();state.mode='code';openTask('desktop');task().draft=include?'Review the release brief and prepare a plan for the Vanta repository. Do not change application code yet.':'Prepare a plan for the selected repository.';save();render();$('#prompt').focus()},
 automations:()=>setView('automations'),'schedule-toggle':()=>{state.schedulePaused=!state.schedulePaused;save();render();announce('Sample schedule '+(state.schedulePaused?'paused':'resumed'))},
 'new-automation':()=>modal('Prepare an automation','<label for="automation-name">Outcome</label><input id="automation-name" value="Check the release status"><p style="margin-top:14px">Full implementation: target, host, account, time zone, budget, expiry, cancellation, and notification policy are reviewed before activation.</p>',btn('Save sample draft','automation-save',true)),
 'automation-save':()=>{closeModal();toast('Sample automation draft prepared. Nothing was scheduled.')},
 'automation-scope':()=>modal('Monitor scope','<div class="code-block">Target: sample release checks\nHost: this Mac\nAccess: read only\nNotify: meaningful change or required decision\nQuiet hours: respected\nCancel: immediately revocable</div>'),
 missed:()=>modal('Missed wake','<p>No result exists for the missed time. Review current state before running again. Unknown external effects are never replayed automatically.</p>',btn('Keep paused','close-dialog',true)),
 output:()=>{state.selectedOutput='direction';m().view='chat';m().panel='outputs';save();render()},reuse,
 recovery:()=>modal('Recover without reconstruction','<p>The partial result, stopped reason, and next safe step remain attached to this run.</p>',btn('Restore draft from checkpoint','reuse',true)+btn('Back','close-dialog')),
 memory:()=>modal('Inspect memory',`<span class="tag">Source: explicit user statement · sample</span><p style="margin-top:16px">Scope: Vanta project. Review: any time. Authority: none.</p><label for="memory-edit">Preference</label><textarea id="memory-edit" rows="3">${esc(state.memoryText||'Prefer a plan before application changes.')}</textarea>`,btn('Save sample correction','memory-save',true)+btn('Archive sample','memory-archive')),
 'memory-save':()=>{state.memoryText=$('#memory-edit').value;state.memoryArchived=false;save();closeModal();render();toast('Sample correction saved. Real Vanta memory was not changed.')},'memory-archive':()=>{state.memoryArchived=true;save();closeModal();render();toast('Sample memory archived. Real Vanta memory was not changed.')},context:()=>{m().view='chat';m().panel='overview';save();render()},
 skill:()=>modal('Research with sources','<p>Installed skill preview · sample</p><div class="code-block">Scope: current task\nBehavior: collect evidence, separate inference\nTools: scoped read-only tools\nAuthority: cannot grant permissions</div>'),
 'skill-toggle':()=>{state.skillEnabled=!state.skillEnabled;save();render()},'skill-install':()=>modal('Inspect before installing','<p>Sample skill from a public source. Review its content, pinned version, capabilities, and source before the real install approval.</p>',btn('Prepare install preview','skill-install-preview',true)),
 'skill-install-preview':()=>{closeModal();toast('Install preview prepared. No skill was downloaded or installed.')},
 connector:()=>modal('Connection scope','<p>GitHub · remote · sample account</p><div class="code-block">Allowed: selected repository metadata\nWrites: require exact-action approval\nRevoke: available at any time\nCredentials: not included in exports</div>',btn('Close','close-dialog',true)),
 'connector-toggle':()=>{state.connectorEnabled=!state.connectorEnabled;save();render()},'add-connection':()=>modal('Add a connection','<p>Choose a remote service or a local MCP server in the full app. This preview does not start an OAuth flow or save a key.</p><div class="menu-list"><button data-action="connector">Remote connector<span>Scope preview</span></button><button data-action="connector">Local MCP server<span>Trust preview</span></button></div>'),
 messaging:()=>modal('Messaging setup','<p>Telegram pairing and gateway controls remain available. The full app shows the active account and target before sending. This prototype does not pair or contact anyone.</p>'),google:()=>modal('Google Workspace setup','<p>Preserve the current OAuth flow and explicit account binding. A provider setup screen cannot establish that a live account is connected.</p>'),
 'worker-pause':()=>{state.workerPaused=true;save();render();announce('Pause requested. The worker has not yet acknowledged a checkpoint.')},
 'new-worker':()=>modal('Prepare a worker','<p>Native Vanta loop is the default. External CLI runtimes must be installed, authenticated, scoped, and approved before use.</p><div class="code-block">Outcome: review selected sample files\nAuthority: read only\nBudget: no paid execution\nDeadline: one bounded run</div>',btn('Keep as draft','close-dialog',true)),
 tickets:()=>modal('Tickets','<p>Existing tickets, dependencies, assignment, and completion gates remain in Workers & budgets. A ticket that requires an artifact cannot close on model narration alone.</p>'),budget:()=>modal('Budget & authority','<p>Spend is labelled Estimated, Reported, or Not reported. Raising a budget or starting an external worker requires a scoped approval.</p>'),activity:()=>modal('Worker activity','<p>Sample activity: task queued → scoped read → pause requested. The pause remains a request until acknowledged.</p>'),
 layouts:()=>modal('Workspace layouts','<p>Keep the existing layout engine. The default is conversation plus an optional context rail; advanced splits, tabs, pane swapping, presets, and detached windows stay reachable.</p><div class="menu-list"><button data-action="layout-conversation">Conversation<span>Default</span></button><button data-action="layout-review">Conversation + review<span>Code</span></button><button data-action="mini">Compact window<span>Preview</span></button></div>'),
 'layout-conversation':()=>{closeModal();m().view='chat';m().panel=null;save();render()},'layout-review':()=>{closeModal();m().view='chat';m().panel='changes';save();render()},
 mini:()=>{closeModal();state.mini=!state.mini;m().view='chat';render();toast(state.mini?'Compact preview. Press Escape to return.':'Full workspace restored.')},
 providers:()=>modal('Model providers','<p>Keep configured providers, local models, model downloads, custom endpoints, effort, speed, and auth recovery.</p><div class="code-block">Automatic routing: capability + quality + budget\nActive route: visible per run\nLocal models: tool eligibility shown explicitly\nMissing key: reconnect, preserve request\nCost: never displayed as zero when unknown</div>'),
 profiles:()=>{closeModal();setView('profiles')},
 authority:()=>modal('Authority stays with you',`<p>Mode: <strong>${esc(state.permission)}</strong>. Switching Chat and Code does not change it.</p><p>Vanta’s autonomy levels R0–R5 remain separate from these working-mode presets. The kernel independently decides Allow, Ask, or Block.</p><p>Recurring authority remains gated until its complete boundary is proven.</p>`),
 runtime:()=>modal('Runtime status','<p>This is an independent browser prototype. There is no live Vanta Engine, model provider, OS bridge, or background executor.</p><p>The full app should show authenticating, starting, ready, stale, reconnecting, stopped, and failed states distinctly.</p>'),
 network:()=>{state.offline=!state.offline;save();render();announce(state.offline?'Offline. Drafts preserved.':'Sample reconnected. Queued work remains paused.')},
 'save-comment':()=>{const text=$('#diff-note').value.trim();if(!text){$('#diff-note').focus();return}state.notes.push(text);save();render();toast('Sample review comment saved.')},
 'terminal-command':()=>{const input=$('#terminal-input').value.trim();const result=$('#terminal-result');result.hidden=false;result.textContent=input==='help'?'Available demonstration commands: help, status. No command execution is possible.':input==='status'?'Prototype only. No repository access.':`“${input}” was not executed. This terminal is a safe sample.`},
 'refresh-preview':()=>toast('Sample preview refreshed. No external navigation.'),
 'copy-output':async()=>{try{await navigator.clipboard.writeText(outputText());toast('Sample output copied.')}catch{modal('Copy sample output','<textarea rows="5" readonly>Vanta desktop direction: one app, Chat and Code, shared projects and outputs, scoped authority.</textarea>')}},
 download:()=>{const blob=new Blob([outputText()],{type:'text/markdown'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=state.selectedOutput==='brief'?'vanta-sample-brief.md':'vanta-sample-direction.md';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Sample Markdown download prepared.')},
 canvas:()=>modal('Canvas · sample result','<div class="subnav"><button data-action="canvas-chart" aria-pressed="true">Chart</button><button data-action="canvas-table">Table</button><button data-action="canvas-board">Board</button></div><div id="canvas-content"><p>Preservation inventory</p><div class="progress-track"><span style="width:83%"></span></div><p class="small muted">245 shell entries + 51 Vanta capabilities. This chart uses sample presentation of the inspected inventory, not runtime acceptance.</p></div>'),
 'canvas-chart':()=>{$('#canvas-content').innerHTML='<p>Preservation inventory</p><div class="progress-track"><span style="width:83%"></span></div><p class="small muted">245 shell entries / 51 Vanta capabilities</p>'},
 'canvas-table':()=>{$('#canvas-content').innerHTML='<table class="table"><tr><th>Inventory</th><th>Entries</th></tr><tr><td>Shell</td><td>245</td></tr><tr><td>Vanta capabilities</td><td>51</td></tr></table>'},
 'canvas-board':()=>{$('#canvas-content').innerHTML='<div class="row">Preserve engine <span class="tag">Required</span></div><div class="row">Redesign shell <span class="tag">Proposed</span></div><div class="row">Native acceptance <span class="tag">Not executed</span></div>'},
 reset:()=>modal('Reset this prototype?','<p>This clears only this design prototype’s browser state. Vanta, its profiles, and your files are untouched.</p>',btn('Reset sample data','reset-confirm',true)+btn('Cancel','close-dialog')),
 'reset-confirm':()=>{for(const pending of runTimers.values())clearTimeout(pending);runTimers.clear();clearTimeout(timer);closeModal();state=structuredClone(initial);save();render();toast('Prototype reset.')},
 guide:()=>modal('Try the full workflow','<ol class="bare-list"><li class="row">1. Type a draft in Code, switch to Chat, then return. It stays.</li><li class="row">2. Open Task context and start a sample run. Try Stop.</li><li class="row">3. Choose Manual, run again, and review the exact sample approval.</li></ol><p>Then explore Today, Automations, Library, and Connections. The full capability map and phased plan are supplied alongside this prototype.</p>',btn('Start in Code','guide-start',true)),
 'guide-start':()=>{closeModal();state.mode='code';openTask('desktop');m().panel='overview';save();render()}
};
function searchResults(query){const q=query.toLowerCase();$('#search-results').innerHTML=Object.entries(state.tasks).filter(([,t])=>t.profile===state.profile&&!t.archived&&(t.title+' '+t.project+' '+t.mode).toLowerCase().includes(q)).map(([id,t])=>`<button data-search-task="${id}">${icon('file')}${esc(t.title)}<span>${t.mode==='code'?'Code':'Chat'}</span></button>`).join('')||'<p class="empty">No matching conversations.</p>'}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.mode)switchMode(b.dataset.mode);else if(b.dataset.sessionMenu){state.menuTask=b.dataset.sessionMenu;actions['session-menu']()}else if(b.dataset.starter){task().draft=b.dataset.starter;save();render();$('#prompt').focus()}else if(b.dataset.profile){selectProfile(b.dataset.profile)}else if(b.dataset.restoreTask){state.tasks[b.dataset.restoreTask].archived=false;save();render();toast('Sample conversation restored.')}else if(b.dataset.output){state.selectedOutput=b.dataset.output;m().view='chat';m().panel='outputs';save();render()}else if(b.dataset.feature){featureDetail(b.dataset.feature)}else if(b.dataset.workerTab){state.workerTab=b.dataset.workerTab;save();render()}else if(b.dataset.connection){connectionDetail(b.dataset.connection)}else if(b.dataset.view){if(b.closest('.primary')&&b.dataset.view==='library')state.tab='Outputs';closeModal();setView(b.dataset.view)}else if(b.dataset.task){state.mode=state.tasks[b.dataset.task].mode;openTask(b.dataset.task)}else if(b.dataset.searchTask){const id=b.dataset.searchTask;closeModal();state.mode=state.tasks[id].mode;openTask(id)}else if(b.dataset.panel){if(b.dataset.panel==='outputs')state.selectedOutput='direction';closeModal();if(m().view!=='chat')m().view='chat';m().panel=m().panel===b.dataset.panel?null:b.dataset.panel;save();render()}else if(b.dataset.file){currentPanelFile=b.dataset.file;m().panel='files';save();render()}else if(b.dataset.tab){state.tab=b.dataset.tab;save();render()}else if(b.dataset.remove!==undefined){attachments().splice(Number(b.dataset.remove),1);save();render()}else if(b.dataset.queue){const i=Number(b.dataset.q);if(b.dataset.queue==='remove')queue().splice(i,1);if(b.dataset.queue==='up'&&i>0)[queue()[i-1],queue()[i]]=[queue()[i],queue()[i-1]];if(b.dataset.queue==='edit'){task().draft=queue().splice(i,1)[0]}state.queueRevision++;save();render()}else if(b.dataset.action){if(b.dataset.action==='session-menu')state.menuTask=m().session;actions[b.dataset.action]?.(b)}});
document.addEventListener('submit',e=>{if(e.target.id==='composer-form'){e.preventDefault();send()}if(e.target.id==='capture-form'){e.preventDefault();const v=$('#capture').value.trim();if(v){state.captured.push(v);save();render();announce('Captured as a private sample draft.')}}});
document.addEventListener('input',e=>{if(e.target.id==='prompt'){task().draft=e.target.value;save()}if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='feature-search')filterFeatures(e.target.value);if(e.target.id==='library-search')$$('[data-searchable]').forEach(el=>el.hidden=!el.dataset.searchable.toLowerCase().includes(e.target.value.toLowerCase()))});
document.addEventListener('change',e=>{const id=e.target.id;if(['theme','support','model','effort'].includes(id)){state[id]=e.target.value;save();if(id==='model'&&state.model==='Choose a provider…')actions.providers();else render()}if(['quiet','stream'].includes(id)){state[id]=e.target.checked;save()}if(id==='permission'){if(e.target.value==='fullAccess'){e.target.value=state.permission;modal('Full access is a separate decision','<p>The full application must show the existing per-project acknowledgement and consequences. This prototype keeps your current mode and does not grant access.</p>',btn('Keep current mode','close-dialog',true))}else{state.permission=e.target.value;save();render();announce('Sample permission mode changed to '+state.permission)}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog').open&&$('#app').classList.contains('sidebar-mobile')){$('#app').classList.remove('sidebar-mobile');return}if(e.key==='Escape'&&!$('#dialog').open&&!state.mini&&matchMedia('(max-width:1150px)').matches&&m().panel){m().panel=null;save();render();return}if(e.key==='Escape'&&state.mini&&!$('#dialog').open){state.mini=false;render();return}if(e.target.id==='prompt'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();actions.search()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='n'&&!$('#dialog').open){e.preventDefault();actions.new()}if((e.metaKey||e.ctrlKey)&&e.key===','){e.preventDefault();closeModal();setView('settings')}});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
window.addEventListener('beforeunload',save);

function reframeComposer(){const form=$('#composer-form');if(!form)return;const controls=form.querySelector('.composer-controls');const options=document.createElement('div');options.className='composer-options';for(const el of [...controls.querySelectorAll('label,select')])options.append(el);form.after(options);const attach=controls.querySelector('[data-action="attach"]');const voice=controls.querySelector('[data-action="voice"]');const input=form.querySelector('textarea');const inputRow=document.createElement('div');inputRow.className='composer-input-row';form.insertBefore(inputRow,input);inputRow.append(attach,input,voice);const send=controls.querySelector('.send');inputRow.append(send);controls.remove();}
function featuresView(){return `<div class="page">${heading('Feature preservation','Review artifact · all existing inventory entries, not runtime certification.')}<input class="search-input" id="feature-search" aria-label="Search preservation map" placeholder="Find a Vanta feature…"><p class="small muted">245 shell features + 51 Vanta capabilities. Every entry retains its source and destination. Dated inventory status is not current acceptance evidence.</p><div id="feature-list">${(window.PRESERVATION||[]).map(f=>`<button class="feature-row" data-feature="${f.id}" data-feature-text="${esc((f.id+' '+f.feature+' '+f.category).toLowerCase())}"><span class="tag">${f.id}</span><span>${esc(f.feature)}</span><span>↗</span></button>`).join('')}</div></div>`}
function filterFeatures(query){$$('[data-feature-text]').forEach(el=>el.hidden=!el.dataset.featureText.includes(query.toLowerCase()))}
function featureDetail(id){const f=(window.PRESERVATION||[]).find(x=>x.id===id);if(!f)return;modal(esc(f.id)+' · '+esc(f.feature),`<p>${esc(f.decision)}</p><dl><dt>Destination</dt><dd>${esc(f.proposed_destination)}</dd><dt>Evidence</dt><dd>${esc(f.evidence_level)}</dd><dt>Inventory source</dt><dd>${esc(f.category)} · line ${f.source_line}</dd></dl><p class="small muted">This entry is a preservation requirement. It is not a claim that its complete runtime path is implemented in this prototype.</p>`)}
const profileDefaults={support:'on',quiet:true,stream:false,notes:[],captured:[],customSchedules:[],memoryText:'Prefer a plan before application changes.',memoryArchived:false,wakeEnabled:false,skillEnabled:true,connectorEnabled:true,workerPaused:false,workerDraft:'',sampleBudget:10,workflowPaused:false,workflowCancelled:false,model:'Auto · balanced',effort:'Medium',selectedOutput:null};
function selectProfile(name){$('#app').classList.remove('sidebar-mobile');state.profilePreferences??={};state.profilePreferences[state.profile]=Object.fromEntries(Object.keys(profileDefaults).map(k=>[k,structuredClone(state[k]??profileDefaults[k])]));Object.assign(state,structuredClone(state.profilePreferences[name]||profileDefaults));state.profileStates??={};state.profileStates[state.profile]=structuredClone(state.modes);state.profile=name;if(state.profileStates[name])state.modes=structuredClone(state.profileStates[name]);else{state.modes={};for(const mode of ['chat','code']){const id='profile-'+name+'-'+mode;state.tasks[id]={title:'New conversation',project:name,profile:name,mode,draft:'',messages:[]};state.modes[mode]={view:'chat',session:id,panel:mode==='code'?'overview':null}}}state.permission='plan';save();render();toast('Sample profile selected. Permission mode starts at Plan.')}
function profilesView(){return `<div class="page">${heading('Profiles','Local profiles. Keep work and preferences separate on this Mac.',btn('Create profile','profile-new',true))}${state.profiles.map(name=>row('folder',esc(name),'Scoped conversations, preferences, projects, and connections.',`<button class="btn" data-profile="${esc(name)}">${state.profile===name?'Selected':'Switch'}</button>`,state.profile===name?'Active':'' )).join('')}<section class="section"><h2>Manage the selected profile</h2><div class="actions">${btn('Clone profile','profile-clone')}${btn('Import sample profile','profile-import')}${btn('Export sample profile','profile-export')}</div><p class="keyboard-note">Credentials, approval grants, and trusted-device state never transfer with a profile export. Each destination requires fresh authorization.</p></section></div>`}
Object.assign(actions,{
'support-on':()=>{state.support='on';save();render()},
features:()=>{closeModal();setView('features')},connections:()=>{closeModal();setView('connections')},workers:()=>{closeModal();setView('workers')},
'profile-new':()=>modal('Create profile','<label for="profile-name">Profile name</label><input id="profile-name" placeholder="For example: Research">',btn('Create sample profile','profile-save',true)),
'profile-save':()=>{const name=$('#profile-name').value.trim();if(!name)return;if(!state.profiles.includes(name))state.profiles.push(name);save();closeModal();render();toast('Sample profile created. Use Switch to select it.')},
'profile-clone':()=>{let name=state.profile+' copy',n=2;while(state.profiles.includes(name))name=state.profile+' copy '+n++;state.profiles.push(name);state.profilePreferences??={};state.profilePreferences[name]=Object.fromEntries(Object.keys(profileDefaults).map(k=>[k,structuredClone(state[k]??profileDefaults[k])]));const ids={};for(const [id,t] of Object.entries(state.tasks)){if(t.profile!==state.profile||t.archived)continue;const cloned='clone-'+name+'-'+id;ids[id]=cloned;state.tasks[cloned]={...structuredClone(t),profile:name,runState:'unverified',completed:false,receipt:null,queue:[]}}state.profileStates??={};state.profileStates[name]=Object.fromEntries(Object.entries(state.modes).map(([mode,v])=>[mode,{...structuredClone(v),session:ids[v.session]}]));save();render();toast('Sample profile cloned with its conversations and preferences; credentials and authority excluded.')},
'profile-import':()=>{if(!state.profiles.includes('Imported sample'))state.profiles.push('Imported sample');save();render();toast('Imported a synthetic profile. No credentials or files were read.')},
'profile-export':()=>{const blob=new Blob([JSON.stringify({profile:state.profile,credentials:'excluded',authority:'requires fresh authorization'},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='vanta-sample-profile.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)},
'session-menu':()=>{state.menuTask??=m().session;modal('Conversation options',`<div class="menu-list"><button data-action="session-rename">Rename</button><button data-action="session-pin">${state.tasks[state.menuTask||m().session].pinned?'Unpin':'Pin'}</button><button data-action="session-branch">Branch into a new conversation</button><button data-action="session-archive">Archive<span>Preserve, don’t delete</span></button><button data-action="layouts">Open in split / tab<span>Layout preview</span></button></div>`)},
'session-rename':()=>{const t=state.tasks[state.menuTask||m().session];modal('Rename conversation',`<label for="session-name">Title</label><input id="session-name" value="${esc(t.title)}">`,btn('Save title','session-rename-save',true))},
'session-rename-save':()=>{const t=state.tasks[state.menuTask||m().session];const v=$('#session-name').value.trim();if(v)t.title=v;closeModal();save();render()},
'session-pin':()=>{const t=state.tasks[state.menuTask||m().session];t.pinned=!t.pinned;closeModal();save();render();toast(t.pinned?'Sample conversation pinned.':'Sample conversation unpinned.')},
'session-branch':()=>{const old=state.tasks[state.menuTask||m().session],id='branch-'+Date.now();state.tasks[id]={...structuredClone(old),title:old.title+' · branch',runState:'unverified',completed:false,receipt:null,queue:[]};closeModal();openTask(id)},
'session-archive':()=>{const t=state.tasks[state.menuTask||m().session];t.archived=true;closeModal();save();render();toast('Sample conversation archived and retained. View it in the run library.')},
'new-automation':()=>modal('Prepare an automation','<label for="automation-name">Name</label><input id="automation-name" value="Check the release status"><label for="automation-time">Time</label><input id="automation-time" type="time" value="09:00"><label for="automation-zone">Time zone</label><input id="automation-zone" value="Europe/Madrid"><p style="margin-top:16px">Local host · read only · notify only on meaningful change. This saves a sample draft, not a live schedule.</p>',btn('Save sample draft','automation-save',true)),
'automation-save':()=>{state.customSchedules.push({name:$('#automation-name').value||'Untitled automation',time:$('#automation-time').value,zone:$('#automation-zone').value});save();closeModal();render();toast('Sample automation draft saved.')},
'model-download':()=>modal('Local model downloads','<p>Sample download queue. No model bytes will be downloaded.</p><div class="row"><strong>Local coding model</strong><span class="tag" id="download-state">Queued</span></div><div class="progress-track"><span id="download-progress" style="width:0"></span></div>',btn('Simulate download','model-download-start',true)+btn('Cancel sample','model-download-cancel')),
'model-download-start':()=>{$('#download-state').textContent='Ready · sample';$('#download-progress').style.width='100%'},
'model-download-cancel':()=>{$('#download-state').textContent='Cancelled';$('#download-progress').style.width='0'},
'providers':()=>modal('Models & providers','<label for="provider-preview">Provider</label><select id="provider-preview"><option>Existing configured provider</option><option>Ollama · local</option><option>LM Studio · local</option><option>Custom endpoint</option></select><label for="endpoint-preview">Endpoint preview</label><input id="endpoint-preview" value="http://127.0.0.1:11434"><p style="margin-top:16px">Provider keys belong in the real secure setup flow. This prototype does not collect or test keys.</p>',btn('Local model downloads','model-download')+btn('Inspect route status','route-status')),
'route-status':()=>modal('Route status','<div class="code-block">Provider: sample only\nModel capability: declared, not executed\nTool eligibility: inspect before running\nLatency: not measured\nActual cost: not reported\nAuth recovery: preserve request, reconnect, retry explicitly</div>'),
'voice':()=>modal('Voice & capture',`<div class="menu-list"><button data-action="voice-sample">${icon('mic')}Try sample dictation<span>No microphone access</span></button><button data-action="wake-toggle">Wake word: Hey Vanta<span>${state.wakeEnabled?'On · sample':'Off'}</span></button><button data-action="capture-preview">Selection / window / screen capture<span>Preview</span></button></div>`),
'wake-toggle':()=>{state.wakeEnabled=!state.wakeEnabled;save();actions.voice()},
'new-worker':()=>modal('Prepare a worker','<label for="worker-outcome">Outcome</label><input id="worker-outcome" value="Review selected project files"><label for="worker-runtime">Runtime</label><select id="worker-runtime"><option>Native Vanta loop</option><option>External CLI · setup required</option></select><p style="margin-top:16px">Project-scoped · read only · one bounded run · actual spend not reported.</p>',btn('Save sample worker draft','worker-save',true)),
'worker-save':()=>{state.workerDraft=$('#worker-outcome').value;save();closeModal();render();toast('Worker draft saved. Nothing started.')},
'worker-checkpoint':()=>{state.workerPaused='acknowledged';save();render();announce('The simulated worker acknowledged its pause checkpoint.')},
'workflow-pause':()=>{state.workflowPaused=!state.workflowPaused;save();render()},
'workflow-cancel':()=>{state.workflowCancelled=true;save();render()},
'budget-save':()=>{state.sampleBudget=$('#budget-limit').value;save();toast('Sample budget draft saved. No spending authority granted.')}
});
const oldAutomationView=automationView;automationView=()=>oldAutomationView().replace('<section class="section"><h2>When this Mac sleeps</h2>',state.customSchedules.map(x=>row('clock',esc(x.name),esc(x.time+' · '+x.zone)+' · Draft; not active',btn('Review scope','automation-scope'),'Draft')).join('')+`<section class="section"><h2>Workflow runs</h2><div class="workflow-graph"><span>Collect sources</span><span>→</span><span>Review gate</span><span>→</span><span>Prepare output</span></div><p class="small muted">Sample ledger · ${state.workflowCancelled?'Stopped':state.workflowPaused?'Pause requested':'Waiting at review gate'}. Pause takes effect only at an acknowledged checkpoint.</p><div class="actions">${btn(state.workflowPaused?'Resume request':'Request pause','workflow-pause')}${btn('Cancel sample run','workflow-cancel')}${btn('Copy / inspect handoff','recovery')}</div></section><section class="section"><h2>When this Mac sleeps</h2>`);
const oldConnections=connectionsView;connectionsView=()=>`<div class="page">${heading('Connections','Vanta’s integration catalog. All states here are synthetic.',btn('Add connection','add-connection'))}<div class="connection-grid">${['GitHub','Trello','Dropbox','Box','Google Workspace','Atlassian Rovo','Slack','Telegram','Local MCP'].map(name=>`<button class="connection-tile" data-connection="${name}"><span class="integration-letter">${name[0]}</span><strong>${name}</strong><small>${name==='Local MCP'?'Local server':name==='Telegram'?'Messaging':'Remote service'}</small><span class="tag">Setup preview</span></button>`).join('')}</div><section class="section"><h2>Project files</h2>${row('folder','Selected project','Local capability · access remains scoped.',btn(state.connectorEnabled?'Turn off':'Turn on','connector-toggle'),state.connectorEnabled?'On · sample':'Off')}</section></div>`;
function connectionDetail(name){modal(esc(name),`<p>${esc(name)} setup preview. No account is connected by this prototype.</p><div class="code-block">Account binding: required in real setup\nAccess: selected scope only\nWrites: exact action approval\nTrust: revocable\nSecrets: excluded from profile export</div><p>Keep Test, Configure, Trust, Revoke, and Status in the real integration.</p>`,btn('Keep as setup draft','close-dialog',true))}
workersView=()=>`<div class="page">${heading('Workers & budgets','Vanta’s existing Company capabilities, in an advanced view.',btn('Prepare worker','new-worker'))}<div class="subnav" role="group" aria-label="Worker sections">${['Workers','Tickets','Budgets','Activity'].map(t=>`<button data-worker-tab="${t}" aria-pressed="${state.workerTab===t}">${t}</button>`).join('')}</div>${state.workerTab==='Workers'?`${row('terminal','Release reviewer',state.workerPaused==='acknowledged'?'Paused at sample checkpoint':state.workerPaused?'Pause requested; waiting for checkpoint':'Native Vanta loop · sample run',state.workerPaused===true?btn('Acknowledge sample checkpoint','worker-checkpoint'):btn('Request pause','worker-pause'),state.workerPaused==='acknowledged'?'Paused':'Running')}${state.workerDraft?row('file',esc(state.workerDraft),'Prepared worker; not started','','Draft'):''}`:state.workerTab==='Tickets'?`<table class="table"><tr><th>Ticket</th><th>WorkItem state</th><th>Evidence</th></tr><tr><td>Preserve all Vanta features</td><td>unverified</td><td>Inventory mapped; runtime proof pending</td></tr><tr><td>Implement Chat / Code shell</td><td>draft</td><td>Design approval pending</td></tr></table><p class="keyboard-note">Closing a ticket requires its declared artifact and evidence.</p>`:state.workerTab==='Budgets'?`<label class="label" for="budget-limit">Draft budget limit (sample units)</label><input id="budget-limit" type="number" value="${esc(state.sampleBudget||10)}" min="0"><div class="actions" style="margin-top:16px">${btn('Save budget draft','budget-save',true)}</div><p class="keyboard-note">Estimated: illustrative only. Actual provider cost: not reported. This does not grant spending authority.</p>`:`<div class="row">Task prepared <span class="tag">draft</span></div><div class="row">Read-only worker running <span class="tag">running</span></div><div class="row">Checkpoint status <span class="tag">${state.workerPaused?'Pause requested':'No new event'}</span></div>`}</div>`;
const cardLibrary=libraryView;
libraryView=()=>{let html=cardLibrary();if(state.tab==='Runs'){const archived=Object.entries(state.tasks).filter(([,t])=>t.archived&&t.profile===state.profile);if(archived.length)html=html.slice(0,-6)+'<section class="section"><h2>Archived conversations</h2>'+archived.map(([id,t])=>row('file',esc(t.title),'Preserved with its draft and history.',`<button class="btn" data-restore-task="${id}">Restore</button>`,'Archived')).join('')+'</section></div>';return html}if(state.tab!=='Outputs')return html;const a=html.indexOf('<input class="search-input"');return html.slice(0,a)+`<input class="search-input" id="library-search" aria-label="Search outputs" placeholder="Search outputs…"><div class="artifact-grid"><button class="artifact-tile" data-searchable="desktop direction markdown" data-output="direction"><span class="artifact-preview"><span class="paper"><span></span><span></span><span></span><span></span><span></span></span></span><span class="artifact-info"><strong>Desktop direction</strong><small>Markdown · Vanta · sample output</small></span></button><button class="artifact-tile" data-searchable="research release brief" data-output="brief"><span class="artifact-preview"><span class="paper"><span></span><span></span><span></span><span></span></span></span><span class="artifact-info"><strong>Release research brief</strong><small>Document · Research · sample output</small></span></button><button class="artifact-tile" data-searchable="canvas chart release checks" data-action="canvas"><span class="artifact-preview"><span class="artifact-bars"><i></i><i></i><i></i><i></i></span></span><span class="artifact-info"><strong>Release checks</strong><small>Canvas · chart, table & board</small></span></button><button class="artifact-tile" data-searchable="code shell proposal" data-panel="changes"><span class="artifact-preview"><span class="artifact-code">&lt;Workspace&gt;<br>&nbsp; &lt;ChatAndCode /&gt;<br>&nbsp; &lt;ProjectSessions /&gt;<br>&nbsp; &lt;ContextRail /&gt;<br>&lt;/Workspace&gt;</span></span><span class="artifact-info"><strong>Shell proposal</strong><small>Code · proposed changes only</small></span></button></div></div>`};
const previousRenderPanel=renderPanel;
renderPanel=()=>{previousRenderPanel();if(m().panel==='outputs'&&state.selectedOutput==='brief'){const paper=$('#inspector .preview-paper');if(paper)paper.innerHTML='<h2>Release research brief</h2><p>Sample document prepared in Chat.</p><p><strong>Outcome:</strong> decide the next release scope.</p><p><strong>Evidence:</strong> separate inspected source, documented behavior, and runtime gaps.</p><p><strong>Next step:</strong> hand a scoped draft to Code after review.</p>'}};

function cardKey(details){return state.profile+':'+m().session+':'+details.className+':'+details.querySelector('summary').textContent.replace(/\s+/g,' ').trim()}
function restoreCards(){state.cardState??={};for(const d of $$('.inline-plan-card,.rail-card')){const k=cardKey(d);if(k in state.cardState)d.open=state.cardState[k]}}
document.addEventListener('click',event=>{const summary=event.target.closest('summary');const details=summary?.parentElement;if(!details||!details.matches('.inline-plan-card,.rail-card'))return;event.preventDefault();details.open=!details.open;state.cardState??={};state.cardState[cardKey(details)]=details.open;save()},true);

render();
